 if(frame>=9000&&!south_reloc){south_reloc=1;int ids[]={48,53,54,55,56,57};for(unsigned k=0;k<sizeof(ids)/sizeof(ids[0]);k++){int v=ids[k];if(u[v].alive&&u[v].owner==SIDE&&(u[v].raw_type==42||u[v].raw_type==37||u[v].raw_type==38)){int ok=order(v,u[v].raw_type==42?MENU_MOVE:MENU_ATTACK,(v==48||v==55||v==56)?1328:1344,(v==48||v==55||v==56)?1848:1808);printf(" SOUTH_RELOC slot%d ok%d frame%d\n",v,ok,frame);}}}if(frame>=7600){for(int i=68;i<MAX_UNITS;i++)if(!deploy[i]&&u[i].alive&&u[i].owner==SIDE&&u[i].type==U_HYDRALISK&&u[i].y<1000){deploy[i]=1;int ok=order(i,MENU_ATTACK,1770,500);printf(" deployed hydra%d ok%d frame%d alive%d\n",i,ok,frame,u[i].alive);break;}}if(frame>=10480&&frame%10==0){int ids[]={48,55,56,86,98,102};for(unsigned q=0;q<sizeof(ids)/sizeof(ids[0]);q++){int j=ids[q];printf(" DETAIL frame%d slot%d alive%d owner%d raw%d hp%d xy%d,%d order%d\n",frame,j,u[j].alive,u[j].owner,u[j].raw_type,u[j].hp,u[j].x,u[j].y,u[j].order);}for(int j=0;j<MAX_UNITS;j++)if(u[j].alive&&u[j].raw_type==74)printf(" RAID frame%d slot%d hp%d shield%d xy%d,%d hidden%d visible%d\n",frame,j,u[j].hp,u[j].shield,u[j].x,u[j].y,race_z8_unit_hidden_from_side(j),currently_visible(u[j].x,u[j].y));}if(frame>=10200&&frame%120==0){int d[]={48,53,54,55,56,57};for(unsigned q=0;q<sizeof(d)/sizeof(d[0]);q++){int i=d[q];printf(" SOUTH_STATE frame%d slot%d alive%d owner%d raw%d hp%d xy%d,%d order%d\n",frame,i,u[i].alive,u[i].owner,u[i].raw_type,u[i].hp,u[i].x,u[i].y,u[i].order);}for(int i=0;i<MAX_UNITS;i++)if(u[i].alive&&u[i].raw_type==74)printf(" DT_STATE frame%d slot%d hp%d shield%d xy%d,%d hidden%d visible%d\n",frame,i,u[i].hp,u[i].shield,u[i].x,u[i].y,race_z8_unit_hidden_from_side(i),currently_visible(u[i].x,u[i].y));}if(frame>=10350&&!advance){advance=1;for(int i=68;i<MAX_UNITS;i++)if(reinf_track[i]==2&&u[i].alive&&u[i].owner==SIDE&&u[i].type==U_HYDRALISK){int ok=order(i,MENU_ATTACK,1390,1810);printf(" ADVANCE slot%d ok%d frame%d\n",i,ok,frame);}}
